-- The CLEP fold's live side (SkyTeaberry, 2026-11-01; Sam's ruling, Open Asks Sheet 150 card 2, 'fold').
-- 1. Re-points 33 saved title assignments from a folded credential to College Board's exam name.
-- 2. Moves 3 credential panel rows to the exam's key, only where that key holds no row for the field.
-- Guarded: a row changes only while it still holds its before-value. Before-values and the rollback:
-- clep_kb_curation_update_receipt.json beside this file. Expect 33 + 3 rows returned.
with m(course_id,field,before,after) as (values ('_UNCLASSIFIED::CLEP French Language (Levels 1 and 2) - Complete both','unified_title_assignment','French Language (Levels 1 and 2)','CLEP French Language'),('_UNCLASSIFIED::CLEP German Language (Levels 1 and 2) - Complete both','unified_title_assignment','German Language (Levels 1 and 2)','CLEP German Language'),('_UNCLASSIFIED::CLEP Spanish Language (Levels 1 and 2) - Complete both','unified_title_assignment','Spanish Language (Levels 1 and 2)','CLEP Spanish Language'),('_UNCLASSIFIED::CLEP French Language Level I (ACE Recommended Score of 50)','unified_title_assignment','CLEP French Language Level 1','CLEP French Language'),('_UNCLASSIFIED::CLEP French Language Level II (ACE Recommended Score of 59)','unified_title_assignment','CLEP French Language Level 2','CLEP French Language'),('_UNCLASSIFIED::CLEP French Language, Level I (Score of 50 or higher)','unified_title_assignment','CLEP French Language Level 1','CLEP French Language'),('_UNCLASSIFIED::CLEP French Language, Level II (Score of 59 or higher)','unified_title_assignment','CLEP French Language Level 2','CLEP French Language'),('_UNCLASSIFIED::CLEP French Language: Level II','unified_title_assignment','CLEP French Language Level 2','CLEP French Language'),('_UNCLASSIFIED::CLEP French Level III','unified_title_assignment','CLEP French Language Level III','CLEP French Language'),('_UNCLASSIFIED::CLEP German Language Level I (ACE Recommended Score of 50)','unified_title_assignment','CLEP German Language Level 1','CLEP German Language'),('_UNCLASSIFIED::CLEP German Language Level II (ACE Recommended Score of 60)','unified_title_assignment','CLEP German Language Level 2','CLEP German Language'),('_UNCLASSIFIED::CLEP German Language, Level I (Score of 50 or higher)','unified_title_assignment','CLEP German Language Level 1','CLEP German Language'),('_UNCLASSIFIED::CLEP German Language, Level II (Score of 60 or higher)','unified_title_assignment','CLEP German Language Level 2','CLEP German Language'),('_UNCLASSIFIED::CLEP German Language: Level II','unified_title_assignment','CLEP German Language Level 2','CLEP German Language'),('_UNCLASSIFIED::CLEP German Level III','unified_title_assignment','CLEP German Language Level III','CLEP German Language'),('_UNCLASSIFIED::CLEP Information Systems and Computer Apps (Score of 50 or higher)','unified_title_assignment','CLEP Information Systems and Computer Applications','CLEP Information Systems'),('_UNCLASSIFIED::CLEP Pre-Calculus (Score of 50)','unified_title_assignment','CLEP Pre-Calculus','CLEP Precalculus'),('_UNCLASSIFIED::CLEP Spanish Language: Level II','unified_title_assignment','CLEP Spanish Language Level 2','CLEP Spanish Language'),('_UNCLASSIFIED::CLEP Spanish Language: Levels 1 and 2','unified_title_assignment','Spanish Language (Levels 1 and 2)','CLEP Spanish Language'),('_UNCLASSIFIED::CLEP Spanish Level I (Score of 50 or higher)','unified_title_assignment','CLEP Spanish Language Level 1','CLEP Spanish Language'),('_UNCLASSIFIED::CLEP Spanish Level II (Score of 63 or higher)','unified_title_assignment','CLEP Spanish Language Level 2','CLEP Spanish Language'),('_UNCLASSIFIED::CLEP Spanish With Writing II','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish and Writing II','unified_title_assignment','CLEP Spanish with Writing 2','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish and Writing Level II','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing I (Score of 50 or higher)','unified_title_assignment','CLEP Spanish with Writing 1','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing Level 2','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing Level II','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing Level II (Score of 63 or higher)','unified_title_assignment','CLEP Spanish with Writing 2','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing Level II (Score of 63)','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing ll','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing: Level 2','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing: Level II','unified_title_assignment','CLEP Spanish with Writing Level II','CLEP Spanish with Writing'),('_UNCLASSIFIED::CLEP Spanish with Writing: Levels 1 and 2','unified_title_assignment','CLEP Spanish with Writing (Levels 1 and 2)','CLEP Spanish with Writing')) update kb_curation k set value=m.after, reviewer_email='cer-clep-fold-skyteaberry@bot', reviewed_at=now() from m where k.course_id=m.course_id and k.field=m.field and k.value=m.before returning k.course_id, k.field, k.value;
with m(course_id,field,before,after) as (values ('_CREDENTIAL_REVIEW::French Language (Levels 1 and 2)','reviewed_marker','1','_CREDENTIAL_REVIEW::CLEP French Language'),('_CREDENTIAL_REVIEW::German Language (Levels 1 and 2)','reviewed_marker','1','_CREDENTIAL_REVIEW::CLEP German Language'),('_CREDENTIAL_REVIEW::Spanish Language (Levels 1 and 2)','reviewed_marker','1','_CREDENTIAL_REVIEW::CLEP Spanish Language')) update kb_curation k set course_id=m.after from m where k.course_id=m.course_id and k.field=m.field and k.value=m.before and not exists (select 1 from kb_curation t where t.course_id=m.after and t.field=m.field) returning k.course_id, k.field, k.value, k.reviewer_email;
